 r={'word_mass':mass,'class_mean_constraint_error':float((A@coeff-targets).abs().max()),'validation_tokens':int(valid.sum()),'all_lexical_fields_correct':int((~errors.any(1)).sum()),'lexical_rms_error':float((pred[:,:21]-labels[ci[valid]]).square().mean().sqrt()),'word_lexical_rms':float(wordout[:,:21].square().mean().sqrt()),'linear_position_error_rms_tokens':float((64*pdiff[:,10]).square().mean().sqrt()),'linear_position_error_max_tokens':float((64*pdiff[:,10]).abs().max()),'linear_position_errors_above_quarter':int((64*pdiff[:,10].abs()>.25).sum()),'periods':periods};reports.append(r);candidates.append({'coefficients':coeff,'bias':intercept,'conditional_native_coefficients':nativeH,'report':r});print(json.dumps(r),flush=True)
